md=["# Prompt video Nexabot (Start Frame to Video, Portrait 9:16, 1080p)\n","Durasi slider = angka di judul. Video tanpa suara; VO ditempel saat edit. Potong ujung klip mengikuti kolom waktu VO.\n"]
for i,(sid,title,text) in enumerate(VO):
    cam,act=M[sid]; d=DUR[i]; a,b=cuts[i],cuts[i+1]
    p=f"{sid} — "+HEAD.format(d=d)+f" Camera: {cam}. Action: {act}"+TAIL
    md.append(f"## {sid} · {title} · {d} detik (VO {a:.2f}–{b:.2f} = {b-a:.2f} dtk)\n\nVO: {text}\n\n```\n{p}\n```\n")
open('prompt_video.md','w').write('\n'.join(md))
